from __future__ import unicode_literals

from .sutool.sutool import ScfcParsingFailedOrInvalidSUToolArgs, NoScfdRuleFilesFound
from .sutool.sutoolwrapper import SUToolWrapper


class ute_common_config_files(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # TODO GLOBAL?

    def migrate_scfc_using_sutool(self,
                                  scfc_path,
                                  output_path,
                                  scfds_source='active partition',
                                  enb_ip='192.168.255.1',
                                  log_path='',
                                  ignore_errors=True):
        """Migrates given SCFC file using SUTool.

        :param string scfc_path: Path to the SCFC file.

        :param string output_path: Path where the migrated SCFC should be saved.

        :param string scfds_source: Source for SCFD files (the migration rules) and for the AdaptationVersions file (TL17/FL17+ only).
        There are three possible sources:

                                    * if scfds_source is a path to an existing directory, it is assumed it contains the required files,

                                    * if scfds_source is a path to an existing file, this file is assumed to be a valid BTSSM- or puttibatti-based
                                      eNB SW package from which the required files should be automatically extracted,

                                    * if scfds_source is equal to 'active partition' or 'passive partition' (ignoring spaces, underscores and
                                      letter case), then all required files will be automatically downloaded from the respective eNB partition,

                                    * if none of the above apply, an error will be raised.

                                    The default source is the active partition of eNB.

        :param string enb_ip: IP address of eNB. Only used if SCFD files are downloaded from eNB. Default: 192.168.255.1.

        :param string log_path: Path where migration logs should be saved. If empty (the default), no log will be generated.

        :param string ignore_errors: If set to true (the default), errors will not cause the keyword to fail and have to be handled manually
                                     based on the returned code. If set to false, the keyword will raise an error if SUTool fails to read
                                     the input SCFC or if no SCFD files are found.
        :returns: Return code of SUTool. According to its README file, it has the following meaning:

                  * 0xFF   invalid arguments or parsing failed

                  * n      conversion result, n is decimal value with following binary representation 0000dcba
                           * d - noRuleFilesFound
                           * c - swFallbackNeeded
                           * b - atLeastOneFaulty
                           * a - atLeastOneMerged

                  To facilitate checking the results of migration, returned value is an integer with additional helper properties:

                  * invalid_args_or_parsing_failed

                  * at_least_one_merged

                  * at_least_one_faulty

                  * sw_fallback_needed

                  * no_rule_files_found

                  For instance, if ${result} is the returned value, ${result.at_least_one_merged} is a boolean that has value True
                  only if at least one migration rule was applied to the input SCFC.
        """
        return_code = SUToolWrapper().migrate_scfc_locally(scfc_path,
                                                           output_path,
                                                           scfds_source=scfds_source,
                                                           enb_ip=enb_ip,
                                                           log_path=log_path)
        if not ignore_errors and return_code.invalid_args_or_parsing_failed:
            raise ScfcParsingFailedOrInvalidSUToolArgs([scfc_path, output_path, scfds_source, log_path])
        elif not ignore_errors and return_code.no_rule_files_found:
            raise NoScfdRuleFilesFound(scfds_source)
        else:
            return return_code
